public static partial class BackyardReverseAuthoring {
static Vector3[] Curve(Vector3[] knots){var points=new List<Vector3>();for(int i=0;i<knots.Length;i++){var a=knots[(i+knots.Length-1)%knots.Length];var b=knots[i];var c=knots[(i+1)%knots.Length];var d=knots[(i+2)%knots.Length];int n=Mathf.Max(2,Mathf.CeilToInt(Vector3.Distance(b,c)/.8f));for(int j=0;j<n;j++){float t=j/(float)n;points.Add(.5f*(2*b+(-a+c)*t+(2*a-5*b+4*c-d)*t*t+(-a+3*b-3*c+d)*t*t*t));}}return points.ToArray();}
static void ResetRoad(RaceRoad r){typeof(RaceRoad).GetField("distance",System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic).SetValue(r,null);r.Initialize();}
public static void Reverse(){
if(Application.isPlaying||UnityEngine.SceneManagement.SceneManager.GetActiveScene().isDirty)throw new Exception("Saved edit mode required");if(File.Exists("Assets/Scenes/DansBackyardReverse.unity"))throw new Exception("Reverse already exists; inspect before regenerating");
Directory.CreateDirectory(Folder);Directory.CreateDirectory(Evidence);report.Clear();EditorSceneManager.OpenScene(BackyardForwardAuthoring.ScenePath);EditorSceneManager.SaveScene(UnityEngine.SceneManagement.SceneManager.GetActiveScene(),"Assets/Scenes/DansBackyardReverse.unity");
var race=Object.FindAnyObjectByType<RaceDirector>();var forward=race.road;forward.Initialize();var forwardPoints=forward.points.ToArray();var street=race.ambientRoad;street.Initialize();
